    H,W=len(inp),len(inp[0])
    ci=[(r,c,inp[r][c]) for r in range(H) for c in range(W) if inp[r][c]!=bg]
    rs=[r for r,c,_ in ci]; cs=[c for _,c,_ in ci]
    ar=min(rs)+max(rs); ac=min(cs)+max(cs)
    out=[[bg]*W for _ in range(H)]
