    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
# for each demo, find pivot (pr,pc) minimizing |ci|+|rot| minus co (must be subset) and check equality
for name in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    inp,out=G[name+' input'],G[name+' output']
    H,W=len(inp),len(inp[0])
    bg=8 if name=='Demo pair 1' else (3 if name=='Demo pair 2' else 1)
    ci={(r,c,v) for r in range(H) for c in range(W) if inp[r][c]!=bg}
    co={(r,c,out[r][c]) for r in range(H) for c in range(W) if out[r][c]!=bg}
    best=[]
    for pr_ in [round(k/2) for k in range(-H,H+1)]:
      for pc_ in [round(l/2) for l in range(-W,W+1)]:
        rot={(round(2*pr_-r),round(2*pc_-c),v) for r,c,v in ci}
        tot=ci|rot
        cov=len(tot&co)
        # extra beyond co must all vanish: cells in tot not in co -> fail unless zero
        bad=len(tot-co)
        best.append((cov,bad,pr_,pc_))
    best.sort(reverse=True)
    print(name, best[:4])

